// Beautiful 3D Isometric cylinder platform component
const IsometricTile: React.FC<{
  x: number;
  y: number;
  size: number;
  thickness: number;
  topColor: string;
  sideColor: string;
  scale: number;
}> = ({ x, y, size, thickness, topColor, sideColor, scale }) => {
  const rx = size * 0.5 * scale;
  const ry = rx * 0.55;

  if (scale <= 0) return null;

  return (
    <svg
      style={{
        position: "absolute",
        left: x - rx,
        top: y - ry - thickness * scale,
        width: rx * 2,
        height: ry * 2 + thickness * scale,
        overflow: "visible",
        pointerEvents: "none",
        transition: "none",
      }}
    >
      {/* 3D Depth / Extrusion Side */}
      <path
        d={`M 0 ${ry} 
            A ${rx} ${ry} 0 0 0 ${rx * 2} ${ry} 
            v ${thickness * scale} 
            A ${rx} ${ry} 0 0 1 0 ${ry + thickness * scale} 
            Z`}
        fill={sideColor}
      />
      {/* Top cap surface */}
      <ellipse cx={rx} cy={ry} rx={rx} ry={ry} fill={topColor} />
    </svg>
  );
};

