// Premium Quadratic Bezier animated curve arrow
const CurvedArrow: React.FC<{
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  cx: number;
  cy: number;
  color: string;
  strokeWidth: number;
  arrowSize: number;
  startProgress: number;
  endProgress: number;
  opacity: number;
}> = ({ x1, y1, x2, y2, cx, cy, color, strokeWidth, arrowSize, startProgress, endProgress, opacity }) => {
  if (endProgress <= startProgress || opacity <= 0) return null;

  // Sample points on the bezier to build precise segment paths and dynamic tangents
  const points: { x: number; y: number; t: number }[] = [];
  const steps = 30;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = (1 - t) * (1 - t) * x1 + 2 * (1 - t) * t * cx + t * t * x2;
    const y = (1 - t) * (1 - t) * y1 + 2 * (1 - t) * t * cy + t * t * y2;
    points.push({ x, y, t });
  }

  const activePoints = points.filter(p => p.t >= startProgress && p.t <= endProgress);
  if (activePoints.length < 2) return null;

  let pathD = `M ${activePoints[0].x} ${activePoints[0].y}`;
  for (let i = 1; i < activePoints.length; i++) {
    pathD += ` L ${activePoints[i].x} ${activePoints[i].y}`;
  }

  const last = activePoints[activePoints.length - 1];
  const prev = activePoints[activePoints.length - 2];
  const dx = last.x - prev.x;
  const dy = last.y - prev.y;
  const angle = Math.atan2(dy, dx);

  const arrowAngle = Math.PI / 6;
  const xTip = last.x;
  const yTip = last.y;
  const xLeft = xTip - arrowSize * Math.cos(angle - arrowAngle);
  const yLeft = yTip - arrowSize * Math.sin(angle - arrowAngle);
  const xRight = xTip - arrowSize * Math.cos(angle + arrowAngle);
  const yRight = yTip - arrowSize * Math.sin(angle + arrowAngle);

  return (
    <svg
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: "100%",
        height: "100%",
        overflow: "visible",
        pointerEvents: "none",
        zIndex: 35,
        transition: "none",
      }}
    >
      <g style={{ opacity, transition: "none" }}>
        <path
          d={pathD}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d={`M ${xTip} ${yTip} L ${xLeft} ${yLeft} L ${xRight} ${yRight} Z`}
          fill={color}
        />
      </g>
    </svg>
  );
};

// Swirling Ellipse Arc Arrow component
const SwirlingLoopArrow: React.FC<{
  cx: number;
  cy: number;
  rx: number;
  ry: number;
  startAngle: number;
  endAngle: number;
  color: string;
  strokeWidth: number;
  arrowSize: number;
  opacity: number;
}> = ({ cx, cy, rx, ry, startAngle, endAngle, color, strokeWidth, arrowSize, opacity }) => {
  if (opacity <= 0) return null;

  const points: { x: number; y: number }[] = [];
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const angle = startAngle + (endAngle - startAngle) * (i / steps);
    const x = cx + rx * Math.cos(angle);
    const y = cy + ry * Math.sin(angle);
    points.push({ x, y });
  }

  if (points.length < 2) return null;

  let pathD = `M ${points[0].x} ${points[0].y}`;
  for (let i = 1; i < points.length; i++) {
    pathD += ` L ${points[i].x} ${points[i].y}`;
  }

  const last = points[points.length - 1];
  const prev = points[points.length - 2];
  const dx = last.x - prev.x;
  const dy = last.y - prev.y;
  const tangentAngle = Math.atan2(dy, dx);

  const arrowAngle = Math.PI / 6;
  const xTip = last.x;
  const yTip = last.y;
  const xLeft = xTip - arrowSize * Math.cos(tangentAngle - arrowAngle);
  const yLeft = yTip - arrowSize * Math.sin(tangentAngle - arrowAngle);
  const xRight = xTip - arrowSize * Math.cos(tangentAngle + arrowAngle);
  const yRight = yTip - arrowSize * Math.sin(tangentAngle + arrowAngle);

  return (
    <svg
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: "100%",
        height: "100%",
        overflow: "visible",
        pointerEvents: "none",
        zIndex: 42,
        transition: "none",
      }}
    >
      <g style={{ opacity, transition: "none" }}>
        <path
          d={pathD}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
        />
        <path
          d={`M ${xTip} ${yTip} L ${xLeft} ${yLeft} L ${xRight} ${yRight} Z`}
          fill={color}
        />
      </g>
    </svg>
  );
};

const IsometricFlowchart: React.FC<IsometricFlowchartProps> = ({
  backgroundColor = "#f9f7f4",
  transparentBackground = false,
  durationInSeconds = 8,
  priyaColor = "#ea580c",
  stampText = "The Permission Loop",
  stampColor = "#b91c1c",
  arrowColor = "#ea580c",
  loopColor = "#dc2626",
  showSpeechBubbles = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Primary timings based on configured FPS
  const stampHitFrame = Math.floor(fps * 5.2);
  const swirlStartFrame = Math.floor(fps * 3.2);

  // Layout calculations
  const priyaX = width * 0.5;
  const priyaY = height * 0.44;

  // Set background transparency safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Nodes for depth sorting (isometric graphics)
  const priyaNode = {
    id: "priya",
    x: priyaX,
    y: priyaY,
    isPriya: true,
    gender: "female" as const,
    hairStyle: "long" as const,
    hairColor: "#111827",
    shirtColor: priyaColor,
    pantsColor: "#0f172a",
    facing: "right" as const,
    platformDelay: Math.floor(fps * 0.3),
    characterDelay: Math.floor(fps * 0.7),
    bubbleDelay: 99999,
  };

  const memberNodes = [
    {
      id: "top-left",
      x: width * 0.28,
      y: height * 0.20,
      isPriya: false,
      gender: "female" as const,
      hairStyle: "long" as const,
      hairColor: "#111827",
      shirtColor: "#ea580c",
      pantsColor: "#0f172a",
      facing: "right" as const,
      platformDelay: Math.floor(fps * 1.0),
      characterDelay: Math.floor(fps * 1.4),
      bubbleDelay: Math.floor(fps * 1.8),
    },
    {
      id: "mid-left",
      x: width * 0.15,
      y: height * 0.40,
      isPriya: false,
      gender: "female" as const,
      hairStyle: "bun" as const,
      hairColor: "#111827",
      shirtColor: "#334155",
      pantsColor: "#0f172a",
      facing: "right" as const,
      platformDelay: Math.floor(fps * 1.2),
      characterDelay: Math.floor(fps * 1.6),
      bubbleDelay: Math.floor(fps * 2.0),
    },
    {
      id: "bot-left",
      x: width * 0.22,
      y: height * 0.61,
      isPriya: false,
      gender: "male" as const,
      hairStyle: "short" as const,
      hairColor: "#111827",
      shirtColor: "#334155",
      pantsColor: "#0f172a",
      facing: "right" as const,
      platformDelay: Math.floor(fps * 1.4),
      characterDelay: Math.floor(fps * 1.8),
      bubbleDelay: Math.floor(fps * 2.2),
    },
    {
      id: "bot-center",
      x: width * 0.49,
      y: height * 0.79,
      isPriya: false,
      gender: "female" as const,
      hairStyle: "long" as const,
      hairColor: "#111827",
      shirtColor: "#334155",
      pantsColor: "#0f172a",
      facing: "right" as const,
      platformDelay: Math.floor(fps * 1.6),
      characterDelay: Math.floor(fps * 2.0),
      bubbleDelay: Math.floor(fps * 2.4),
    },
    {
      id: "bot-right",
      x: width * 0.67,
      y: height * 0.73,
      isPriya: false,
      gender: "female" as const,
      hairStyle: "bun" as const,
      hairColor: "#111827",
      shirtColor: "#ea580c",
      pantsColor: "#0f172a",
      facing: "left" as const,
      platformDelay: Math.floor(fps * 1.5),
      characterDelay: Math.floor(fps * 1.9),
      bubbleDelay: Math.floor(fps * 2.3),
    },
    {
      id: "mid-right",
      x: width * 0.85,
      y: height * 0.40,
      isPriya: false,
      gender: "male" as const,
      hairStyle: "short" as const,
      hairColor: "#111827",
      shirtColor: "#ea580c",
      pantsColor: "#0f172a",
      facing: "left" as const,
      platformDelay: Math.floor(fps * 1.3),
      characterDelay: Math.floor(fps * 1.7),
      bubbleDelay: Math.floor(fps * 2.1),
    },
    {
      id: "top-right",
      x: width * 0.72,
      y: height * 0.20,
      isPriya: false,
      gender: "male" as const,
      hairStyle: "short" as const,
      hairColor: "#111827",
      shirtColor: "#334155",
      pantsColor: "#0f172a",
      facing: "left" as const,
      platformDelay: Math.floor(fps * 1.1),
      characterDelay: Math.floor(fps * 1.5),
      bubbleDelay: Math.floor(fps * 1.9),
    },
  ];

  // Deep sort (Y-sorting) all items on screen to handle perspective overlap elegantly
  const sortedNodes = [priyaNode, ...memberNodes].sort((a, b) => a.y - b.y);

  // Concentric background visual guide tracks
  const bgTracksOpacity = interpolate(frame, [10, 45], [0, 0.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Stamp impact screen shake effect
  let shakeX = 0;
  let shakeY = 0;
  if (frame >= stampHitFrame && frame < stampHitFrame + 14) {
    const dt = frame - stampHitFrame;
    const intensity = interpolate(dt, [0, 14], [25, 0], { extrapolateRight: "clamp" });
    shakeX = intensity * Math.sin(dt * 1.8) * (random(`shake-x-${dt}`) - 0.5);
    shakeY = intensity * Math.cos(dt * 1.8) * (random(`shake-y-${dt}`) - 0.5);
  }

  // Stamp slam spring physics
  const stampSpring = spring({
    frame: frame - stampHitFrame,
    fps,
    config: { damping: 10, stiffness: 120, mass: 0.8 },
  });

  const stampScale = interpolate(stampSpring, [0, 1], [4.5, 1]);
  const stampOpacity = interpolate(frame - stampHitFrame, [0, 3], [0, 1], { extrapolateRight: "clamp" });

  // Visual impact flash
  const flashOpacity = interpolate(frame, [stampHitFrame, stampHitFrame + 7], [0.35, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Arrow bombardment wave controls (fade them down when stamp hits)
  const bombardmentAlpha = interpolate(frame, [stampHitFrame, stampHitFrame + 15], [1, 0.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Locked ring presentation
  const lockedRingOpacity = interpolate(frame, [stampHitFrame, stampHitFrame + 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Swirling active loops before locking
  const swirlDrawIn = interpolate(frame, [swirlStartFrame, swirlStartFrame + 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const swirlFadeOut = interpolate(frame, [stampHitFrame, stampHitFrame + 10], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const swirlRotateOffset = (frame * 2.8 * Math.PI) / 180;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Visual Impact Flash */}
      {flashOpacity > 0 && (
        <AbsoluteFill
          style={{
            backgroundColor: stampColor,
            opacity: flashOpacity,
            zIndex: 99,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Primary Layout Container with screen shake applied */}
      <div
        style={{
          width: "100%",
          height: "100%",
          position: "relative",
          transform: `translate(${shakeX}px, ${shakeY}px)`,
          transition: "none",
        }}
      >
        {/* Concentric Flowchart Guide Tracks */}
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            opacity: bgTracksOpacity,
            pointerEvents: "none",
          }}
        >
          <ellipse cx={priyaX} cy={priyaY + 10} rx={width * 0.22} ry={height * 0.12} fill="none" stroke="#e2e8f0" strokeWidth={2.5} strokeDasharray="12 16" />
          <ellipse cx={priyaX} cy={priyaY + 10} rx={width * 0.36} ry={height * 0.20} fill="none" stroke="#e2e8f0" strokeWidth={2.5} strokeDasharray="12 16" />
          <ellipse cx={priyaX} cy={priyaY + 10} rx={width * 0.46} ry={height * 0.26} fill="none" stroke="#cbd5e1" strokeWidth={2} strokeDasharray="8 12" />
        </svg>

        {/* Dynamic Flying Dart Arrows (Questions Bombardment) */}
        {memberNodes.map((node, i) => {
          const relativeFrame = frame - (node.characterDelay + 15) - i * 8;
          if (relativeFrame < 0) return null;

          const loopDuration = 60;
          const cycleFrame = relativeFrame % loopDuration;

          // Animate flying dart segment over first 40 frames of loop
          if (cycleFrame >= 40) return null;

          const progress = cycleFrame / 40;
          const endProgress = interpolate(progress, [0, 0.85], [0, 1], { extrapolateRight: "clamp" });
          const startProgress = interpolate(progress, [0.15, 1], [0, 1], { extrapolateRight: "clamp" });

          const isLeft = node.x < priyaX;
          const bendX = isLeft ? -45 : 45;
          const mx = (node.x + priyaX) / 2;
          const my = ((node.y - 45) + (priyaY - 55)) / 2;

          return (
            <CurvedArrow
              key={`arrow-${node.id}`}
              x1={node.x}
              y1={node.y - 45}
              x2={priyaX}
              y2={priyaY - 55}
              cx={mx + bendX}
              cy={my - 130}
              color={arrowColor}
              strokeWidth={3.5}
              arrowSize={13}
              startProgress={startProgress}
              endProgress={endProgress}
              opacity={bombardmentAlpha}
            />
          );
        })}

        {/* Swirling Circular Loop Arrows (Wrapping around Priya) */}
        {Array.from({ length: 3 }).map((_, i) => {
          const baseAngle = (i * 2 * Math.PI) / 3;
          const span = 1.6; // ~90 degree arc length
          const startA = baseAngle + swirlRotateOffset;
          const endA = startA + span * swirlDrawIn;

          return (
            <SwirlingLoopArrow
              key={`swirl-${i}`}
              cx={priyaX}
              cy={priyaY - 10}
              rx={width * 0.145}
              ry={height * 0.08}
              startAngle={startA}
              endAngle={endA}
              color={arrowColor}
              strokeWidth={4.5}
              arrowSize={14}
              opacity={swirlFadeOut}
            />
          );
        })}

        {/* Permanent Locked Flowchart Ring (Activates when stamp lands) */}
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            overflow: "visible",
            pointerEvents: "none",
            opacity: lockedRingOpacity,
            zIndex: 41,
          }}
        >
          {/* Outer dashed track glowing */}
          <ellipse
            cx={priyaX}
            cy={priyaY - 10}
            rx={width * 0.155}
            ry={height * 0.085}
            fill="none"
            stroke={loopColor}
            strokeWidth={5}
            strokeDasharray="14 10"
            style={{ filter: "drop-shadow(0px 0px 8px rgba(220,38,38,0.5))" }}
          />
          {/* Inner solid ring */}
          <ellipse
            cx={priyaX}
            cy={priyaY - 10}
            rx={width * 0.125}
            ry={height * 0.068}
            fill="none"
            stroke={loopColor}
            strokeWidth={3}
            style={{ filter: "drop-shadow(0px 0px 6px rgba(220,38,38,0.35))" }}
          />
        </svg>

        {/* Render Platforms and Characters Depth-Sorted */}
        {sortedNodes.map((node) => {
          // Platform spring pop-up
          const pSpringValue = spring({
            frame: frame - node.platformDelay,
            fps,
            config: { damping: 13, stiffness: 100 },
          });
          const platformScale = interpolate(pSpringValue, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Character entry pop-up
          const cSpringValue = spring({
            frame: frame - node.characterDelay,
            fps,
            config: { damping: 14, stiffness: 110 },
          });
          const charScale = interpolate(cSpringValue, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const charOpacity = interpolate(cSpringValue, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const charTranslateY = interpolate(cSpringValue, [0, 1], [40, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Question Bubble scale
          const bSpringValue = spring({
            frame: frame - node.bubbleDelay,
            fps,
            config: { damping: 12, stiffness: 120 },
          });
          const bubbleScale = interpolate(bSpringValue, [0, 1], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const charHeight = node.isPriya ? 115 : 85;

          return (
            <React.Fragment key={node.id}>
              {/* Isometric Tile Platform */}
              <IsometricTile
                x={node.x}
                y={node.y}
                size={node.isPriya ? 190 : 105}
                thickness={node.isPriya ? 22 : 14}
                topColor={node.isPriya ? "#ffffff" : "#f1f5f9"}
                sideColor={node.isPriya ? "#cbd5e1" : "#cbd5e1"}
                scale={platformScale}
              />

              {/* Character standing on platform top */}
              <div
                style={{
                  position: "absolute",
                  left: node.x - (charHeight * 0.45) / 2,
                  top: node.y - charHeight,
                  zIndex: 30,
                  pointerEvents: "none",
                  transition: "none",
                }}
              >
                <Character
                  gender={node.gender}
                  shirtColor={node.shirtColor}
                  pantsColor={node.pantsColor}
                  hairColor={node.hairColor}
                  hairStyle={node.hairStyle}
                  height={charHeight}
                  facing={node.facing}
                  isPriya={node.isPriya}
                  scale={charScale}
                  opacity={charOpacity}
                  translateY={charTranslateY}
                />
              </div>

              {/* Question mark bubbles for team members */}
              {!node.isPriya && (
                <SpeechBubble
                  x={node.x + 12}
                  y={node.y - charHeight - 5}
                  scale={bubbleScale}
                  show={showSpeechBubbles}
                />
              )}
            </React.Fragment>
          );
        })}

        {/* Priya Platform Name Badge */}
        {frame >= priyaNode.characterDelay && (
          <div
            style={{
              position: "absolute",
              left: priyaNode.x,
              top: priyaNode.y + 35,
              transform: "translate(-50%, -50%)",
              backgroundColor: "#0f172a",
              color: "white",
              fontFamily: spaceGroteskFamily,
              fontSize: 14,
              fontWeight: "bold",
              padding: "4px 14px",
              borderRadius: 6,
              boxShadow: "0 4px 10px rgba(0,0,0,0.15)",
              textTransform: "uppercase",
              letterSpacing: 1.5,
              zIndex: 32,
              pointerEvents: "none",
              transition: "none",
            }}
          >
            Priya
          </div>
        )}

        {/* The Heavy Red Ink Stamp */}
        {frame >= stampHitFrame && (
          <div
            style={{
              position: "absolute",
              left: "50%",
              bottom: "16%",
              transform: `translateX(-50%) scale(${stampScale}) rotate(-6deg)`,
              transformOrigin: "center center",
              opacity: stampOpacity,
              border: `11px double ${stampColor}`,
              borderRadius: 14,
              padding: "12px 36px",
              backgroundColor: "rgba(251, 251, 251, 0.94)",
              boxShadow: "0 14px 35px rgba(0,0,0,0.14)",
              zIndex: 55,
              pointerEvents: "none",
              display: "inline-block",
              overflow: "hidden",
              transition: "none",
            }}
          >
            <div
              style={{
                fontFamily: oswaldFamily,
                fontSize: 84,
                fontWeight: 900,
                color: stampColor,
                textTransform: "uppercase",
                letterSpacing: 5,
                lineHeight: 1,
                position: "relative",
                userSelect: "none",
                transition: "none",
              }}
            >
              {stampText}

              {/* Distressed ink texture simulation */}
              {grungeElements.map((el, i) => (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: `${el.rx * 100}%`,
                    top: `${el.ry * 100}%`,
                    width: el.rWidth,
                    height: el.rHeight,
                    backgroundColor: backgroundColor, // matches parent canvas style seamlessly
                    transform: `rotate(${el.rRot}deg)`,
                    opacity: 0.88,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default IsometricFlowchart;